.h3 + x.h6 > 0, 12, 4), IF(x.h6 = 1, 6, IF(x.h3 = 1, IF(x.h2 = 1, 6, 3), IF(x.h2 = 1, 2, 1))))) AS base FROM (SELECT x.*, IF(((x.usp IN (3)) + (x.uay IN (3)) + (x.uib IN (3)) + (x.une IN (3)) + (x.uan IN (3)) + (x.usd IN (3)) + (x.usi IN (3))) > 0, 1, 0) AS h8, IF(((x.usp IN (6)) + (x.uay IN (6)) + (x.uib IN (6)) + (x.une IN (6)) + (x.uan IN (6)) + (x.usd IN (6)) + (x.usi IN (6))) > 0, 1, 0) AS h4, IF(((x.usp IN (4)) + (x.uay IN (4)) + (x.uib IN (4)) + (x.une IN (4)) + (x.uan IN (4)) + (x.usd IN (4)) + (x.usi IN (4))) > 0, 1, 0) AS h6, IF(((x.usp IN (8, 16)) + (x.uay IN (8, 16)) + (x.uib IN (8, 16)) + (x.une IN (8, 16)) + (x.uan IN (8, 16)) + (x.usd IN (8, 16)) + (x.usi IN (8, 16))) > 0, 1, 0) AS h3, IF(((x.usp IN (12)) + (x.uay IN (12)) + (x.uib IN (12)) + (x.une IN (12)) + (x.uan IN (12)) + (x.usd IN (12)) + (x.usi IN (12))) > 0, 1, 0) AS h2 FROM (SELECT x.*, IF(x.ib = 0, 0, IF(x.hc = 1 OR x.nsa >= 2, 4, IF(x.ay = 1 AND x.np > 0, (24 - x.usp) DIV 3, 8))) AS uib, IF(x.neact = 1, 4, 0) AS une, IF(x.al = 0 AND x.ap > 0, IF(x.ap = 1, 12, 16), 0) AS uan, IF(x.sact = 1 AND x.nsl = 0, IF(x.nsp = 1, 12, 16), 0) AS usd, IF(x.siact = 1, IF(x.nsi = 1, 4, 8), 0) AS usi FROM (SELECT x.*, IF(x.sact = 1 AND x.nsl > 0, 1, 0) AS sash, IF(x.nsi > 0 AND x.ac = 0 AND x.ay = 0, 1, 0) AS siact, IF((x.nni > 0 AND x.ib = 0) OR (x.nna > 0 AND x.ib = 0 AND x.ay = 0), 1, 0) AS neact, IF(x.np = 0, 0, IF(x.sx = 'P', IF(x.hc = 1, 6, 12), IF(x.hc = 1, 3, 6))) AS usp, IF(x.ay = 0, 0, IF(x.hc = 1, 4, 8)) AS uay FROM (SELECT x.*, IF(x.ac > 0, 1, 0) AS hc, x.ns + x.nsi AS nsa, IF(x.np + x.nalt + x.pg1 + x.pgm + x.ay + x.ib + x.kk + x.nni + x.nna + x.ns + x.nsi = 0, 0, 1) AS ada, IF(x.kk = 1 AND x.ay = 0, 1, 0) AS fbk, IF(x.nna > 0 AND x.ay = 1 AND x.ib = 0, 1, 0) AS fbn, IF(x.ns > 0 AND x.ap > 0 AND x.al = 0 AND x.ay = 0, 1, 0) AS fbs, IF(x.pgm = 1, 1, 0) AS fbp, IF(x.ns > 0 AND x.ac = 0 AND x.ay = 0, 1, 0) AS sact FROM (SELECT x.*, x.al + x.ap AS ac FROM (SELECT x.*, x.nal + x.pgl AS al, x.nap + x.pgp AS ap FROM (SELECT x.*, x.pg1 - x.pgp AS pgl, x.nalt - x.nap AS nal, x.nc - x.ncp AS ncl, x.ns - x.nsp AS nsl FROM (SELECT x.*, IF(x.pas = '', 0, LENGTH(x.pas) - LENGTH(REPLACE(x.pas, ';', '')) + 1) AS np, IF(x.ank = '', 0, LENGTH(x.ank) - LENGTH(REPLACE(x.ank, ';', '')) + 1) AS nalt, ROUND((LENGTH(LOWER(x.ank)) - LENGTH(REPLACE(LOWER(x.ank), ' binti ', ''))) / 7) AS nap, IF(LOCATE(';', x.pgd) > 0, 1, 0) AS pgm, IF((x.pgd <> '') <> (x.cuc <> ''), 1, 0) AS pgmis, IF(x.pgd <> '' AND x.cuc <> '' AND LOCATE(';', x.pgd) = 0, 1, 0) AS pg1, IF(x.pgd <> '' AND x.cuc <> '' AND LOCATE(';', x.pgd) = 0 AND LOWER(x.pgd) LIKE '%binti%', 1, 0) AS pgp, IF(x.cuc = '', 0, LENGTH(x.cuc) - LENGTH(REPLACE(x.cuc, ';', '')) + 1) AS nc, ROUND((LENGTH(LOWER(x.cuc)) - LENGTH(REPLACE(LOWER(x.cuc), ' binti ', ''))) / 7) AS ncp, IF(x.ayh <> '', 1, 0) AS ay, IF(x.ibu <> '', 1, 0) AS ib, IF(x.kak <> '', 1, 0) AS kk, IF(x.ni = '', 0, LENGTH(x.ni) - LENGTH(REPLACE(x.ni, ';', '')) + 1) AS nni, IF(x.na = '', 0, LENGTH(x.na) - LENGTH(REPLACE(x.na, ';', '')) + 1) AS nna, IF(x.sdr = '', 0, LENGTH(x.sdr) - LENGTH(REPLACE(x.sdr, ';', '')) + 1) AS ns, ROUND((LENGTH(LOWER(x.sdr)) - LENGTH(REPLACE(LOWER(x.sdr), ' binti ', ''))) / 7) AS nsp, IF(x.sdi = '', 0, LENGTH(x.sdi) - LENGTH(REPLACE(x.sdi, ';', '')) + 1) AS nsi, ROUND((LENGTH(LOWER(x.sdi)) - LENGTH(REPLACE(LOWER(x.sdi), ' binti ', ''))) / 7) AS nsip FROM (SELECT TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9701 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS pas, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9702 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ank, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks